$types=@{encoder=(BuildType 'encoder');decoder=(BuildType 'decoder')};$bridges=@{}
foreach($direction in @('encoder','decoder')){foreach($write in @($false,$true)){$base=if($direction -eq 'encoder'){[Text.Encoder]}else{[Text.Decoder]};$sourceElement=if($direction -eq 'encoder'){[char]}else{[byte]};$targetElement=if($direction -eq 'encoder'){[byte]}else{[char]};$sourceArray=$sourceElement.MakeArrayType();$targetArray=$targetElement.MakeArrayType();$roDefinition=[type]'System.ReadOnlySpan`1';$spanDefinition=[type]'System.Span`1';$ro=$roDefinition.MakeGenericType([type[]]@($sourceElement));$span=$spanDefinition.MakeGenericType([type[]]@($targetElement));$argsTypes=if($write){[type[]]@($base,$sourceArray,[int],[int],$targetArray,[int],[int],[bool])}else{[type[]]@($base,$sourceArray,[int],[int],[bool])};$nativeArgs=if($write){[type[]]@($ro,$span,[bool])}else{[type[]]@($ro,[bool])};$name=if($direction -eq 'encoder'){if($write){'GetBytes'}else{'GetByteCount'}}else{if($write){'GetChars'}else{'GetCharCount'}};$bridge=[Reflection.Emit.DynamicMethod]::new(('GenericSpan'+$direction+$write),[int],$argsTypes);$il=$bridge.GetILGenerator();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_1);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_2);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_3);$il.Emit([Reflection.Emit.OpCodes]::Newobj,$ro.GetConstructor([type[]]@($sourceArray,[int],[int])));if($write){foreach($i in 4..6){$il.Emit([Reflection.Emit.OpCodes]::Ldarg,[int16]$i)};$il.Emit([Reflection.Emit.OpCodes]::Newobj,$span.GetConstructor([type[]]@($targetArray,[int],[int])));$il.Emit([Reflection.Emit.OpCodes]::Ldarg,[int16]7)}else{$il.Emit([Reflection.Emit.OpCodes]::Ldarg,[int16]4)};$il.Emit([Reflection.Emit.OpCodes]::Callvirt,$base.GetMethod($name,[type[]]$nativeArgs));$il.Emit([Reflection.Emit.OpCodes]::Ret);$func=[type]('System.Func`'+($argsTypes.Count+1));$bridges[$direction+[string]$write]=$bridge.CreateDelegate($func.MakeGenericType([type[]]@($argsTypes+[int])))}}
